// ANCHOR: example
//! Build and read a FlatBuffer using the schema in `my_game.fbs`.
//!
//! The Rust module generated by `flatc --rust` is checked in beside this file,
//! so normal builds do not need the FlatBuffers schema compiler. Regenerate it
//! after changing the schema with FlatBuffers 25.12.19 or a compatible release.

use flatbuffers::FlatBufferBuilder;

#[expect(
    clippy::unwrap_used,
    reason = "flatc emits unwrap for scalar fields that have schema defaults"
)]
#[expect(
    unused_extern_crates,
    reason = "flatc emits alloc for compatibility with no_std consumers"
)]
#[expect(
    explicit_outlives_requirements,
    reason = "flatc emits lifetime bounds that the compiler can infer"
)]
mod my_game_generated {
    include!("my_game_generated.rs");
}

/// Builds, reads, and verifies a FlatBuffer monster record.
fn main() -> anyhow::Result<()> {
    let mut builder = FlatBufferBuilder::new();
    let name = builder.create_string("Alice");
    let monster = my_game_generated::my_game::Monster::create(
        &mut builder,
        &my_game_generated::my_game::MonsterArgs {
            name: Some(name),
            hp: 80,
        },
    );

    builder.finish(monster, None);

    // `root` verifies the buffer and returns a zero-copy view into its bytes.
    let bytes = builder.finished_data();
    let decoded =
        flatbuffers::root::<my_game_generated::my_game::Monster>(bytes)?;
    assert_eq!(decoded.name(), Some("Alice"));
    assert_eq!(decoded.hp(), 80);
    println!("Decoded monster: {decoded:?}");
    Ok(())
}
// ANCHOR_END: example

/// Runs the example.
pub fn run() -> anyhow::Result<()> {
    main()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn flatbuffer_round_trip_preserves_the_monster() -> anyhow::Result<()> {
        main()
    }
}
